        try (PrintWriter writer = new PrintWriter(new FileWriter(filename))) {
            writer.println(password);
            System.out.println("Password saved to the file '" + filename + "'.");
        } catch (IOException e) {
            System.out.println("An error occurred: " + e.getMessage());
        } finally {
