Sure, I'll help you write a JavaScript function that implements the Haversine formula to calculate the distance between two geographical coordinates. The function will take into account the next four parameters for latitude and longitude coordinates, and a fifth boolean indicating the unit of measurement (miles or kilometers). I'll also include some basic validation to handle edge cases and return sensible messages for invalid inputs. Here is the function with an appropriate set of comments and edge cases handling:

```javascript
/**
 * Calculates the distance between two geographical points using the Haversine formula.
 * @param {number} lat1 - Latitude of the first point in degrees
 * @param {number} lon1 - Longitude of the first point in degrees
 * @param {number} lat2 - Latitude of the second point in degrees
 * @param {number} lon2 - Longitude of the second point in degrees
 * @param {boolean} isMetric - Whether the result should be returned in kilometers (true) or miles (false)
 * @returns {number} The distance between the two points in the specified unit of measurement (miles or kilometers).
 */
function calculateDistance(lat1, lon1, lat2, lon2, isMetric) {
    if (!Number.isFinite(lat1) || !Number.isFinite(lon1) || !Number.isFinite(lat2) || !Number.isFinite(lon2)) {
        return { error: "Invalid input coordinates. Coordinates must be finite numbers (e.g., 37.7749, -122.4194)." };
    }

    // Validating coordinates within -90 to 90 for latitude and -180 to 180 for longitude
    if (lat1 < -90 || lat1 > 90 || lon1 < -180 || lon1 > 180 || lat2 < -90 || lat2 > 90 || lon2 < -180 || lon2 > 180) {
        return { error: "Invalid input coordinates. Latitude and Longitude values must be between -90 and 90, and -180 and 180 respectively." };
    }

    // Haversine formula
    const R = isMetric ? 6371 : 3958.8; // Radius of Earth in kilometers or miles
    const phi1 = Math.PI / 180 * lat1;
    const phi2 = Math.PI / 180 * lat2;
    const deltaPhi = Math.PI / 180 * (lat2 - lat1);
    const deltaLambda = Math.PI / 180 * (lon2 - lon1);

    const a = Math.sin(deltaPhi / 2) * Math.sin(deltaPhi / 2) +
              Math.cos(phi1) * Math.cos(phi2) *
              Math.sin(deltaLambda / 2) * Math.sin(deltaLambda / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    const distance = R * c;

    return { distance, unit: isMetric ? "km" : "mi", error: "" };
}

// Example usage:
const { distance, unit, error } = calculateDistance(37.7749, -122.4194, 51.5074, -0.1278, true); // KMs
console.log(`Distance: ${distance} ${unit}, Error: ${error ? error : 'No error.'}`);

const { distance: miles, unit: milesUnit } = calculateDistance(37.7749, -122.4194, 51.5074, -0.1278, false); // Miles
console.log(`Distance: ${miles} ${milesUnit}, Error: ${error ? error : 'No error.'}`);

// Example for edge cases and invalid inputs
const noValidInput = calculateDistance(180, 180, -180, -180, true); // Invalid coordinates
console.log("No valid input coordinates result: ", noValidInput);

const noCoordinates = calculateDistance('invalid', 180, -180, -180, true); // Invalid coordinates
console.log("Invalid coordinates result: ", noCoordinates);

const bothInvalidInput = calculateDistance(90, -180, -90, 180, true); // Invalid coordinates
console.log("Both invalid input coordinates result: ", bothInvalidInput);

