function findSmallestOddGreaterThanThree(): void {
    // Prompt the user to enter an array of integers
    const userInput = prompt("Enter an array of integers separated by spaces: ");
    // Split the user input into an array of strings for now
    const arrayInput = userInput ? userInput.split(" ") : [];
    // Convert the string array to an integer array (assuming all values are integers)
    const integerArray = arrayInput.map(Number) as number[];

    // Check if integerArray is empty and handle it gracefully
    if (integerArray.length === 0) {
        console.log("No input provided or the array is empty.");
        return;
    }

    // Validate the array to ensure all items are numbers (optional)
    if (!integerArray.every(item => typeof item === 'number')) {
        console.log("Invalid input. Please enter only integers.");
        return;
    }

    // Filter the array to keep only odd numbers greater than 3
    const oddGreaterThanThree = integerArray.filter(num => num > 3 && num % 2 !== 0);

    // Check if any odd number greater than 3 exists and handle the case gracefully
    if (oddGreaterThanThree.length === 0) {
        console.log("There are no odd numbers greater than 3 in the array.");
    } else {
        // Find the smallest odd number and print it
        const smallestOddGreaterThanThree = Math.min(...oddGreaterThanThree);
        console.log(`The smallest odd number greater than 3 is: ${smallestOddGreaterThanThree}`);
    }
}

