Certainly! Below is a C++ implementation of a queue data structure that includes methods for adding elements to the front and back, removing elements from the front, checking for emptiness, and handling possible exceptions. The implementation adheres to best practices in naming conventions, code style, and documentation.

```cpp
#include <iostream>
#include <stdexcept>

class Queue {
public:
    // Constructor to initialize the queue
    Queue() : front_(nullptr), back_(nullptr), size_(0) {}

    // Destructor to delete all nodes in the queue
    ~Queue() {
        while (!empty()) {
            Dequeue();
        }
    }

    // Method to add an element to the end of the queue
    void Enqueue(const int& value) {
        Node* newNode = new Node(value);
        if (empty()) {
            front_ = newNode;
            back_ = newNode;
        } else {
            back_->next = newNode;
            back_ = newNode;
        }
        ++size_;
    }

    // Method to add an element to the front of the queue
    void EnqueueToFront(const int& value) {
        Node* newNode = new Node(value);
        if (!empty()) {
            newNode->next = front_;
            front_ = newNode;
        } else {
            front_ = newNode;
            back_ = newNode;
        }
        ++size_;
    }

    // Method to remove and return the front element of the queue
    int Dequeue() {
        if (empty()) {
            throw std::out_of_range("Queue is empty, cannot dequeue.");
        }

        int frontValue = front_->value;
        Node* temp = front_;
        front_ = front_->next;

        if (!front_) {
            back_ = nullptr;
        }

        delete temp;
        --size_;

        return frontValue;
    }

    // Method to check if the queue is empty
    bool empty() const {
        return front_ == nullptr;
    }

    // Method to display the queue elements for debugging
    void PrintQueue() const {
        Node* current = front_;
        std::cout << "Queue: ";
        while (current != nullptr) {
            std::cout << current->value << " -> ";
            current = current->next;
        }
        std::cout << "nullptr\n";
    }

private:
    struct Node {
        int value;
        Node* next;

        Node(int val) : value(val), next(nullptr) {}
    };

    Node* front_;
    Node* back_;
    size_t size_;
};

// Example usage
int main() {
    Queue myQueue;

    try {
        myQueue.Enqueue(10);
        myQueue.Enqueue(20);
        myQueue.Enqueue(30);

        myQueue.EnqueueToFront(5);
        myQueue.EnqueueToFront(15);

        myQueue.PrintQueue();  // Output: Queue: 5 -> 15 -> 10 -> 20 -> 30 -> nullptr
        std::cout << "Queue size: " << myQueue.size_ << std::endl;

        std::cout << "Dequeued: " << myQueue.Dequeue() << std::endl;  // Dequeued: 5

        myQueue.PrintQueue();  // Output: Queue: 15 -> 10 -> 20 -> 30 -> nullptr

        myQueue.Dequeue();  // Dequeued: 15
        myQueue.Dequeue();  // Dequeued: 10
        myQueue.Dequeue();  // Dequeued: 20

        myQueue.PrintQueue();  // Output: Queue: 30 -> nullptr
        myQueue.Dequeue();  // Dequeued: 30

        std::cout << "Queue size after all dequeues: " << myQueue.size_ << std::endl;  // Output: Queue size after all dequeues: 0

        // Uncomment the following line to see exception being thrown
        // myQueue.Dequeue();
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}
```

### Explanation:
- **Class `Queue`**: Contains methods for enqueueing at the end, enqueueing at the front, dequeueing the front, checking for emptiness, and a helper method for displaying the queue for debugging.
- **Node Structure**: Represents each node in the queue with an integer value and a pointer to the next node.
- **Destructor**: Ensures that all nodes are deleted when the `Queue` object is no longer needed.
- **Enqueue and EnqueueToFront**: Add elements to the end of the queue. Enqueue does it, while EnqueueToFront adds an element to the front and shifts the remaining nodes forward.
- **Dequeue**: Removes and returns the front element of the queue. It throws an exception if the queue is empty.

