// Function to determine and display browser information
function displayBrowserInformation() {
    const userAgent = navigator.userAgent;
    const browser = determineBrowser(userAgent);

    // Display results
    const browserInfo = document.getElementById('browserInfo');
    if (browserInfo) {
        // Clear previous output for cleaner display
        browserInfo.innerHTML = '';

        // Bulleted list of browsers
        const listItems = [
            { browser: 'Chrome', versionRange: /Chrome\/(\d+)/ },
            { browser: 'Firefox', versionRange: /Firefox\/(\d+)/ },
            { browser: 'Safari', versionRange: /Version\/(\d+)/ },
            { browser: 'Edge', versionRange: /Edg\/(\d+)/ },
            { browser: 'Internet Explorer', versionRange: /MSIE|Trident\/\d+\.+\d+/ }
        ];

        // Find the relevant info for each browser and construct the display string
        const browserNames = listItems.map(item => {
            if (item.versionRange.test(userAgent)) {
                const majorVersion = userAgent.match(item.versionRange)[1];
                return `${item.browser} ${majorVersion}`;
            }
            return '';
        });

        // Create a new HTML list item for each browser match
        const browserList = browserNames.filter(name => name !== '');
        browserList.forEach(name => {
            const listElement = document.createElement('li');
            listElement.textContent = name;
            browserInfo.appendChild(listElement);
        });

        // Display generic browser information if not fully recognized
        if (!browser) {
            const noMatchMessage = document.createElement('p');
            noMatchMessage.textContent = 'Your browser could not be determined.';
            browserInfo.appendChild(noMatchMessage);
        }
    }
}

// Helper function to determine browser based on user agent string
function determineBrowser(userAgent) {
    const chrome = /Chrome\/(\d+)/.test(userAgent);
    const firefox = /Firefox\/(\d+)/.test(userAgent);
    const safari = /Version\/(\d+)/.test(userAgent);
    const edge = /Edg\/(\d+)/.test(userAgent);
    const ie = /MSIE|Trident\/\d+\.+\d+/.test(userAgent);

    if (chrome) return { browser: 'Chrome', versionRange: /Chrome\/(\d+)/ };
    if (firefox) return { browser: 'Firefox', versionRange: /Firefox\/(\d+)/ };
    if (safari) return { browser: 'Safari', versionRange: /Version\/(\d+)/ };
    if (edge) return { browser: 'Edge', versionRange: /Edg\/(\d+)/ };
    if (ie) return { browser: 'Internet Explorer', versionRange: /MSIE|Trident\/\d+\.+\d+/ };

    return { browser: 'Unknown' };
}

// Add event listener to the window to run the detection function on page load and resize
window.addEventListener('load', displayBrowserInformation);
window.addEventListener('resize', displayBrowserInformation);

// Optional: Add a button to the page to manually trigger the browser information display
